theme.css:
#wemd{color:#1f1f1f;background-color:#fdfdfc;font-family:'Source Han Serif SC', 'Noto Serif SC', 'STSong', serif;font-size:17px;line-height:2;letter-spacing:0.05em;text-align:justify;padding:48px 36px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.6em;text-indent:2em}
#wemd h1{font-size:28px;font-weight:400;color:$colors.text_primary;margin-top:2.5em;margin-bottom:1.5em;text-align:center}
#wemd h2{font-size:22px;font-weight:400;color:$colors.text_primary;margin-top:2.2em;margin-bottom:1em;text-align:left;border-bottom:1px solid $colors.border;padding-bottom:.4em}
#wemd h3{font-size:18px;font-weight:600;color:$colors.text_primary;margin-top:1.8em;margin-bottom:0.7em}
#wemd h4{font-size:16px;font-weight:400;color:$colors.text_secondary;margin-top:1.4em;margin-bottom:0.5em}
#wemd blockquote{border-left:3px solid $colors.quote_border;background:$colors.quote_background;padding:14px 22px;color:$colors.text_secondary;font-style:normal;margin:1.2em 0}
#wemd code{background-color:$colors.code_background;color:$colors.text_primary;padding:1px 5px;border-radius:2px;font-size:0.9em;font-family:'Courier New', monospace}
#wemd pre{background:$colors.code_background;border-radius:2px;padding:14px 18px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.border;padding:10px 14px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:$colors.accent}
#wemd hr{border:0;border-top:1px solid $colors.border;margin:3em 0;width:30%}
#wemd img{max-width:100%;height:auto;border-radius:2px}
#wemd figcaption{font-size:13px;color:$colors.text_secondary;text-align:center}
#wemd a{color:$colors.link_color;text-decoration:none}
#wemd strong{color:#434343;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:2px 4px;border-radius:0px}
